#include <vector>

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    // Check if the input size is zero
    if (size == 0) {
        std::cerr << "Empty input detected" << std::endl;
        return 0;
    }

    // Create an in-memory stream from the fuzzed data
    std::vector<char> buffer(size);
    std::streambuf<std::vector<char>> bufferStream(buffer, std::ios::_base::in);

    // Write the fuzz data to the buffer
    for (size_t i = 0; i < size; ++i) {
        bufferStream << data[i];
    }

    std::ios::pos_type pos = bufferStream.tellg();
    if (pos != bufferStream.size()) {
        std::cerr << "Buffer size mismatch" << std::endl;
    }

    // Read the header
    try {
        Header header(bufferStream);
    } catch (const std::exception& e) {
        std::cerr << "Failed to read header: " << e.what() << std::endl;
        return 0;
    }

    // Process each part of the file
    for (std::uint i = 0; i < header.numParts(); ++i) {
        MultiPartInputFile partFile(bufferStream, i);
    }

    return 0;
}

